const path = decodeURIComponent(location.pathname).replace(/\/+$/,'');
let language = localStorage.getItem('agi-language') === 'en' ? 'en' : 'es';
const english = window.AGI_EN || {};
const translate = value => english[value] || value;
const translateDeep = value => Array.isArray(value) ? value.map(translateDeep) : value && typeof value === 'object' ? Object.fromEntries(Object.entries(value).map(([key,item])=>[key,translateDeep(item)])) : typeof value === 'string' ? translate(value) : value;
